#include <stddef.h>
#include <stdint.h>
#include <string.h>
static size_t base(size_t d,size_t i){return 2+d+i*(d+2);}
static int valid_tree(const int64_t*v,size_t d,size_t n,int i,uint8_t*seen,size_t*count){if(i<0)return 1;if((size_t)i>=n||seen[i])return 0;seen[i]=1;(*count)++;size_t b=base(d,(size_t)i);int64_t l=v[b+d],r=v[b+d+1];if(l>=0&&l==r)return 0;return valid_tree(v,d,n,(int)l,seen,count)&&valid_tree(v,d,n,(int)r,seen,count);}
static void search(const int64_t*v,size_t d,int i,size_t depth,const int64_t*q,int64_t*best,int64_t*bestd,int64_t*visited){if(i<0)return;(*visited)++;size_t b=base(d,(size_t)i);int64_t dist=0;for(size_t k=0;k<d;k++){int64_t z=q[k]-v[b+k];dist+=z*z;}if(dist<*bestd){*bestd=dist;for(size_t k=0;k<d;k++)best[k]=v[b+k];}size_t axis=depth%d;int64_t left=v[b+d],right=v[b+d+1];int near,far;if(q[axis]<=v[b+axis]){near=(int)left;far=(int)right;}else{near=(int)right;far=(int)left;}search(v,d,near,depth+1,q,best,bestd,visited);int64_t split=q[axis]-v[b+axis];if(split*split<*bestd)search(v,d,far,depth+1,q,best,bestd,visited);}
static void put_i64(uint8_t*out,size_t off,int64_t x){uint64_t b;memcpy(&b,&x,8);for(size_t k=0;k<8;k++)out[off+k]=(uint8_t)(b>>(8*k));}
int64_t nearest_neighbour_search(const int64_t*v,size_t n,uint8_t*out,size_t cap){if(!v||n<5)return -1;int64_t d0=v[0],n0=v[1];if((d0!=2&&d0!=3)||n0<1||n0>15)return -1;size_t d=(size_t)d0,count=(size_t)n0;if(n!=2+d+count*(d+2))return -1;int64_t q[3]={0},best[3]={0};for(size_t k=0;k<d;k++){q[k]=v[2+k];if(q[k]<-1000||q[k]>1000)return -1;}for(size_t i=0;i<count;i++){size_t b=base(d,i);for(size_t k=0;k<d;k++)if(v[b+k]<-1000||v[b+k]>1000)return -1;int64_t l=v[b+d],r=v[b+d+1];if(l < -1||l>=n0||r < -1||r>=n0)return -1;}uint8_t seen[15]={0};size_t reached=0;if(!valid_tree(v,d,count,0,seen,&reached)||reached!=count)return -1;int64_t bestd=INT64_MAX,visited=0;search(v,d,0,0,q,best,&bestd,&visited);if(!out||cap<48)return -2;int64_t result[6]={(int64_t)d,best[0],best[1],d==3?best[2]:0,bestd,visited};for(size_t k=0;k<6;k++)put_i64(out,k*8,result[k]);return 48;}
